const body = $json.body || {};
const kw = body.keyword || body.target_keyword || '';
let prompt = (body.prompt || '').trim();

if (!prompt && kw) {
  prompt = 'modern photorealistic 4k commercial product photography of ' + kw + ', studio lighting, high resolution, crisp details, no text, no watermarks';
} else if (!prompt) {
  prompt = 'modern high-tech digital workspace with glowing futuristic interfaces, 4k ultra-realistic photography, no text';
}

prompt = prompt.replace(/[\r\n]+/g, ' ').trim();
const width = body.width || 1200;
const height = body.height || 630;
const model = body.model || 'flux';
const seed = body.seed || (Math.floor(Math.random() * 999999) + 1);

const imgUrl = 'https://image.pollinations.ai/prompt/' + encodeURIComponent(prompt) + '?width=' + width + '&height=' + height + '&nologo=true&model=' + model + '&seed=' + seed;

return [{
  json: {
    prompt: prompt,
    image_url: imgUrl,
    keyword: kw,
    width: width,
    height: height,
    model: model,
    seed: seed
  }
}];

let b64 = '';
let mime = 'image/jpeg';

try {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  if (buffer) {
    b64 = buffer.toString('base64');
  }
} catch (e) {
  if ($input.first().binary && $input.first().binary.data) {
    b64 = $input.first().binary.data.data || '';
    mime = $input.first().binary.data.mimeType || 'image/jpeg';
  }
}

const reqData = $('Prepare Image Request').first().json;

return [{
  json: {
    status: b64 ? 'success' : 'failed',
    prompt: reqData.prompt,
    image_url: reqData.image_url,
    image_b64: b64,
    featured_image_b64: b64,
    mime_type: mime,
    size_bytes: b64 ? Math.round((b64.length * 3) / 4) : 0
  }
}];
